            row.projectionParameter=Vector3.Dot(Flat(row.position-row.segmentStart),delta)/delta.sqrMagnitude;float t=Mathf.Clamp01(row.projectionParameter);
            row.projection=new Vector3(row.segmentStart.x+delta.x*t,row.position.y,row.segmentStart.z+delta.z*t);row.lateralDelta=Flat(row.projection-row.position);row.crossTrackError=row.lateralDelta.magnitude;row.projectionKnown=true;
            // Same owned policy as Street accepted-segment correction. Not an original Game rule or a NavMesh-complete claim.
            row.enterThreshold=row.capsule.worldRadius*0.5f;row.exitThreshold=row.capsule.worldRadius*0.25f;row.episodeWalk=homeCorrectionEpisodeWalk;row.episodeNetXZ=homeCorrectionActive?XZ(row.position,homeCorrectionEpisodeStart):0f;
            if(homeCorrectionActive&&(homeCorrectionWaypoint!=row.waypoint||row.crossTrackError<=row.exitThreshold||row.projectionParameter<0f||row.projectionParameter>1f))
            {
                row.exited=true;row.reason=row.crossTrackError<=row.exitThreshold?"Returned to original Home route segment":"Original Home waypoint/projection context changed";homeCorrectionActive=false;
            }
            // Keep a context-change exit attached to its old episode; any new episode may enter on the next real frame.
            if(!homeCorrectionActive&&!row.exited&&row.projectionParameter>=0f&&row.projectionParameter<=1f&&row.crossTrackError>row.enterThreshold)
            {
                homeCorrectionActive=true;homeCorrectionWaypoint=row.waypoint;homeCorrectionEpisode++;homeCorrectionEpisodeStart=row.position;homeCorrectionEpisodeWalk=0f;row.episode=homeCorrectionEpisode;row.episodeWalk=0f;row.episodeNetXZ=0f;row.entered=true;row.reason="Ordinary SDK lateral keys toward original Home route projection";
            }
            row.active=homeCorrectionActive;
            if(homeCorrectionActive){keys=Steering(s.moveRootPosition,s.cameraPosition,row.position+row.lateralDelta.normalized,out s.heading);row.queuedKeys=string.Join<InputKey>("+",keys);s.phase="normal-SDK-Home-lateral-correction";}
            if(row.entered||row.exited)RecordHomeCorrection(row,cc,s.movement==null?Vector3.zero:s.movement.moveV);
            return homeCorrectionActive;
        }

    }
}
